import sys

def solve():
    input_data = sys.stdin.read().split()
    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    r_min, r_max = H, -1
    c_min, c_max = W, -1

    for i, row in enumerate(grid):
        for j, ch in enumerate(row):
            if ch == '#':
                r_min = min(r_min, i)
                r_max = max(r_max, i)
                c_min = min(c_min, j)
                c_max = max(c_max, j)

    for i in range(r_min, r_max + 1):
        for j in range(c_min, c_max + 1):
            if grid[i][j] == '.':
                print("No")
                return

    print("Yes")

if __name__ == "__main__":
    solve()
